pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz the depositor address and an amount to deposit. The general invariant:
    // After a depositor deposits amount > 0 and then calls withdrawAll(), the contract's internal
    // 'balance' (accessible via the auto-generated getter) must equal the sum of all credits in the mapping.
    // In the correct contract, after withdrawAll by that depositor the depositor's credit becomes 0 and
    // the contract's internal balance is decreased accordingly, so the invariant (balance == sum credits)
    // holds for all inputs. The mutant that omits decrementing the internal balance breaks this invariant
    // for some inputs (the contract's balance will be larger than sum of credits).
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a real address (not zero) and amount in a reasonable range but wide
        vm.assume(depositor != address(0));
        amount = bound(amount, 0, 1 ether);

        // We need a positive deposit to exercise withdraw path meaningfully
        vm.assume(amount > 0);

        // Fund depositor and perform deposit
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Record the sum of credits by reading the depositor's credit (mapping is not public in given C,
        // but we can observe the contract's external balance and its public 'balance' variable).
        // The intended universal invariant to check: c.balance() equals address(c).balance if and only if
        // the mapping sums to that value. Since we cannot iterate mapping, we use a single-depositor scenario:
        // After deposit and withdrawAll by the same depositor, the depositor's credit must be zero and
        // the contract's internal 'balance' must equal address(c).balance (i.e., no discrepancy between internal accounting and actual ETH held).

        // Execute withdrawAll as depositor
        vm.prank(depositor);
        c.withdrawAll();

        // Single assertion reading contract's public state: the contract's recorded balance must equal the actual ETH held.
        // This holds for the correct contract for all admissible inputs; the mutant that does not decrement internal balance
        // will cause c.balance() != address(c).balance for some inputs and thus fail this assertion.
        assertTrue(c.balance() == address(c).balance);
    }
}

