            ok = false;
        }

        // The general invariant: after withdrawAll completes, c.credit(attacker) == 0
        // Accessing mapping credit is possible only if it had a public getter; in the given contract it's not public
        // but we can reason via address(c).balance: for the reference contract, after successful withdraw the contract balance decreased by depositAmount
        // However the required rule in the prompt asks to assert on c's PUBLIC surface; since credit has no getter, we assert that the contract's balance is 0 after a successful withdraw
        // For our scenario: attacker deposited `depositAmount` and then withdrew; in the correct contract, if withdraw succeeded, address(c).balance must be 0
        if (ok) {
            assertTrue(address(c).balance == 0);
        } else {
            // If the call reverted, the invariant about balance after success is not applicable; still assert that balance is <= depositAmount
            assertTrue(address(c).balance <= depositAmount);
        }
    }
}

// Attacker contract that re-enters C during receive()
