contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: amount to deposit, we also fuzz an unused address to satisfy the requirement
    function testFuzz_property(uint256 amount, address dummy) public {
        // keep amount in a reasonable domain (non-zero and not absurdly large)
        amount = bound(amount, 1, 1 ether);

        // Deploy a reentrant attacker that will try to reenter withdrawAll during the external call
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund the attacker so it can deposit and receive refunds
        vm.deal(address(attacker), amount);

        // Have attacker deposit amount as its credit
        attacker.doDeposit{value: amount}();

        // Now trigger withdrawAll from attacker which will reenter once during the external call
        // The reference contract zeros credit before the external call, so the reentrancy cannot withdraw twice
        // The mutant zeros after the external call and can be reentered to withdraw again, leaving stored credit non-zero
        bool ok;
        try attacker.doWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: after withdrawAll returns (regardless of revert), the stored credit for attacker must be zero in the reference.
        // We observe this via the public getter for the mapping: credit is not public, but we can check address(c).balance and effect of further withdraws.
        // To directly observe the invariant in a way that distinguishes the mutant, we attempt a second withdrawAll: in the reference it should do nothing (no funds left to withdraw), so the attacker balance should not increase.

        // Record attacker's balance now
        uint256 balBefore = address(attacker).balance;

        // Try withdrawing again; use try/catch because mutant may revert due to unexpected state
        try attacker.doWithdraw() {
            // no revert
        } catch {
            // ignore
        }

        uint256 balAfter = address(attacker).balance;

        // The reference ensures no additional funds are sent on the second withdraw (credit was zeroed before first external call).
        // Therefore balAfter should equal balBefore for the reference; the mutant will have performed a successful reentrant double-withdraw
        // and balAfter > balBefore for some inputs. We assert the invariant that in the correct contract, no extra funds were transferred on the second withdraw.
        assertTrue(balAfter == balBefore);
    }
}

// Minimal reentrant attacker that will call back into C.withdrawAll when receiving Ether
contract ReentrantAttacker {
    C target;
    bool reentered;

    constructor(address _target) {
        target = C(_target);
        reentered = false;
    }

    // deposit into target
    function doDeposit() external payable {
        target.deposit{value: msg.value}();
    }

    // start withdraw process
    function doWithdraw() external {
        target.withdrawAll();
    }

    // receive hook: attempt to reenter only once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // reenter withdrawAll during the external call
            target.withdrawAll();
        }
    }
}
